type DoctorOptions struct {
	Dir string
}

func RunDoctorCLI(args []string, stdout, stderr io.Writer) int {
	if isHelpArg(args) {
		printDoctorUsage(stdout)
		return contract.ExitOK
	}

opts := DoctorOptions{Dir: "."}
	fs := newDoctorFlagSet(&opts, stderr)
	if err := fs.Parse(args); err != nil {
		return contract.ExitUsage
	}
	if fs.NArg() != 0 {
		fs.Usage()
		return contract.ExitUsage
	}

result, err := RunDoctor(opts, DoctorDependencies{})
	if err != nil {
		fmt.Fprintf(stderr, "aidlc doctor: %v\n", err)
		return contract.ExitUsage
	}
	printDoctorResult(stdout, result)
	if len(result.Findings) > 0 {
		return contract.ExitConflict
	}
	return contract.ExitOK
}

func newDoctorFlagSet(opts *DoctorOptions, stderr io.Writer) *flag.FlagSet {
	fs := flag.NewFlagSet("aidlc doctor", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.StringVar(&opts.Dir, "dir", opts.Dir, "repository directory to inspect")
	fs.Usage = func() { printDoctorUsage(stderr) }
	return fs
}

func RunDoctor(opts DoctorOptions, deps DoctorDependencies) (DoctorResult, error) {
	deps = doctorDependenciesWithDefaults(deps)
	dir := strings.TrimSpace(opts.Dir)
	if dir == "" {
		return DoctorResult{}, fmt.Errorf("--dir must not be empty")
	}
	repoDir, err := filepath.Abs(dir)
	if err != nil {
		return DoctorResult{}, err
	}
	info, err := deps.Stat(repoDir)
	if err != nil {
		return DoctorResult{}, fmt.Errorf("inspect --dir: %w", err)
	}
	if !info.IsDir() {
		return DoctorResult{}, fmt.Errorf("--dir is not a directory: %s", repoDir)
	}

var stdout, stderr bytes.Buffer
	code := runDoctorForTest([]string{"--dir", root}, &stdout, &stderr, DoctorDependencies{
		ExecutablePath: pathBinary,
		Version:        "v1.2.3",
		PathEnv:        pathDir,
		HomeDir:        home,
		GoOS:           "linux",
		Executable: func(path string) bool {
			return path == pathBinary || path == commonBinary
		},
	})

if code != contract.ExitOK {
		t.Fatalf("doctor code = %d, stderr = %q, stdout = %q", code, stderr.String(), stdout.String())
	}
	for _, want := range []string{
		"version: v1.2.3",
		"executable: " + pathBinary,
		"PATH discoverable: yes",
		commonBinary + " [executable]",
		"Makefile: " + filepath.Join(root, "Makefile") + " (includes .ai/Makefile.inc)",
		"status: healthy",
	} {
		if !strings.Contains(stdout.String(), want) {
			t.Fatalf("stdout missing %q:\n%s", want, stdout.String())
		}
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", stderr.String())
	}
}

var stdout, stderr bytes.Buffer
	code := runDoctorForTest([]string{"--dir", root}, &stdout, &stderr, DoctorDependencies{
		ExecutablePath: executable,
		Version:        "dev",
		PathEnv:        filepath.Join(t.TempDir(), "path-bin"),
		HomeDir:        home,
		GoOS:           "linux",
		Executable: func(path string) bool {
			return path == executable
		},
	})

if code != contract.ExitConflict {
		t.Fatalf("doctor code = %d, stderr = %q, stdout = %q", code, stderr.String(), stdout.String())
	}
	for _, want := range []string{
		"PATH discoverable: no",
		executable + " [executable]",
		"root Makefile does not include .ai/Makefile.inc",
		"For sanitized IDE shells or CI, set AIDLC_BIN",
		"AIDLC_BIN=" + executable + " make ai-doctor",
		"Ensure the repository root Makefile includes: -include .ai/Makefile.inc",
	} {
		if !strings.Contains(stdout.String(), want) {
			t.Fatalf("stdout missing %q:\n%s", want, stdout.String())
		}
	}
	if stderr.Len() != 0 {
		t.Fatalf("stderr = %q, want empty", stderr.String())
	}
}

result, err := RunDoctor(DoctorOptions{Dir: root}, DoctorDependencies{
		ExecutablePath: pathBinary,
		Version:        "dev",
		PathEnv:        pathDir,
		HomeDir:        t.TempDir(),
		GoOS:           "linux",
		Executable: func(path string) bool {
			return path == pathBinary
		},
	})
	if err != nil {
		t.Fatalf("RunDoctor() error = %v", err)
	}
	joined := strings.Join(result.Findings, "\n")
	for _, want := range []string{
		".ai/Makefile.inc is missing",
	} {
		if !strings.Contains(joined, want) {
			t.Fatalf("findings missing %q: %#v", want, result.Findings)
		}
	}
	if strings.Contains(joined, "root Makefile is missing") {
		t.Fatalf("missing Makefile should not be reported when helper is absent: %#v", result.Findings)
	}

const (
	DefaultGitHubURL = "https://github.com/shubhangtiwari/aidlc"
	DefaultRef       = "main"
