func RunInitCLI(ctx context.Context, args []string, stdout, stderr io.Writer) int {
	if isHelpArg(args) {
		printInitUsage(stdout)
		return contract.ExitOK
	}

fs.Usage = func() { printInitUsage(stderr) }
	if err := fs.Parse(flagArgs); err != nil {
		return contract.ExitUsage
	}
	if len(positionals) != 1 || fs.NArg() != 0 {
		fs.Usage()
		return contract.ExitUsage
	}
	ide, err := contract.ParseIDE(positionals[0])
	if err != nil {
		fmt.Fprintf(stderr, "aidlc init: %v\n", err)
		return contract.ExitUsage
	}
	opts.IDE = ide

result, err := RunInit(ctx, opts)
	printCommandResult(stdout, result)
	if err != nil {
		fmt.Fprintf(stderr, "aidlc init: %v\n", err)
		return contract.ExitUsage
	}
	if hasConflict(result.Plan) {
		return contract.ExitConflict
	}
	return contract.ExitOK
}

func splitInitCLIArgs(args []string) ([]string, []string) {
	flagArgs := []string{}
	positionals := []string{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if strings.HasPrefix(arg, "-") && arg != "-" {
			flagArgs = append(flagArgs, arg)
			if initFlagNeedsValue(arg) && i+1 < len(args) {
				i++
				flagArgs = append(flagArgs, args[i])
			}
			continue
		}
		positionals = append(positionals, arg)
	}
	return flagArgs, positionals
}

func initFlagNeedsValue(arg string) bool {
	name := strings.TrimLeft(arg, "-")
	if strings.Contains(name, "=") {
		return false
	}
	switch name {
	case "source", "url", "ref", "path":
		return true
	default:
		return false
	}
}

func RunInit(ctx context.Context, opts contract.InitOptions) (CommandResult, error) {
	if opts.TargetDir == "" {
		opts.TargetDir = "."
	}
	previous, err := templatesync.ReadManifest(opts.TargetDir)
	if err != nil {
		return CommandResult{}, err
	}
	provider, normalizedSource, err := providerFor(opts.Source)
	if err != nil {
		return CommandResult{}, err
	}
	opts.Source = normalizedSource

func TestInitCopiesOnlyPublicManifestPathsAndGeneratesIDE(t *testing.T) {
	source := createTemplateSource(t)
	target := t.TempDir()

result, err := RunInit(context.Background(), contract.InitOptions{
		IDE:       contract.IDECodex,
		TargetDir: target,
		Source: contract.SourceOptions{
			Kind: "local",
			Path: source,
			Ref:  "test",
		},
	})
	if err != nil {
		t.Fatalf("init: %v", err)
	}
	if hasConflict(result.Plan) {
		t.Fatal("init reported conflicts")
	}

func TestInitDryRunDoesNotWritePayloadOrGeneratedFiles(t *testing.T) {
	source := createTemplateSource(t)
	target := t.TempDir()

result, err := RunInit(context.Background(), contract.InitOptions{
		IDE:       contract.IDECodex,
		TargetDir: target,
		Source:    contract.SourceOptions{Kind: "local", Path: source},
		DryRun:    true,
	})
	if err != nil {
		t.Fatalf("init dry run: %v", err)
	}
	if len(result.Written) != 0 || len(result.Generated) != 0 {
		t.Fatalf("dry run wrote files: %#v", result)
	}
	assertMissing(t, target, ".ai/README.md")
	assertMissing(t, target, "AGENTS.md")
	assertMissing(t, target, contract.TargetManifestPath)
}

result, err := RunInit(context.Background(), contract.InitOptions{
		IDE:       contract.IDECodex,
		TargetDir: target,
		Source:    contract.SourceOptions{Kind: "local", Path: source},
	})
	if err != nil {
		t.Fatalf("init: %v", err)
	}
	if hasConflict(result.Plan) {
		t.Fatal("unexpected conflict")
	}
	if got := testutil.ReadFile(t, target, "LICENSE"); got != "local license edits" {
		t.Fatalf("divergent file overwritten: %q", got)
	}
	if got := testutil.ReadFile(t, target, "licenses/aidlc.md"); got != "license\n" {
		t.Fatalf("mapped license payload = %q", got)
	}
	assertExists(t, target, ".ai/README.md")
	assertExists(t, target, ".ai/models.defaults.toml")
	assertExists(t, target, "AGENTS.md")
	assertExists(t, target, ".codex/agents/architect.toml")
	assertExists(t, target, contract.TargetManifestPath)
	assertGenerated(t, result.Generated, "AGENTS.md")

manifest := readTargetManifest(t, target)
	if manifestHasFile(manifest, "LICENSE") {
		t.Fatal("init lock recorded consumer root LICENSE")
	}
	if !manifestHasFile(manifest, "licenses/aidlc.md") {
		t.Fatal("init lock omitted mapped AIDLC license payload path")
	}
	if !manifestHasFile(manifest, ".ai/README.md") || !manifestHasFile(manifest, ".ai/models.defaults.toml") {
		t.Fatal("init lock omitted accepted payload path")
	}
	assertIDESelection(t, manifest.Workspace.IDEs, []contract.IDE{contract.IDECodex})
}

type MapOptions struct {
	Dir     string
	Check   bool
	Include []string
}

type MapDependencies struct {
	CacheBuilder  model.CacheBuilder
	Stdin         io.Reader
	IsInteractive func() bool
}

func (mapDeclinedError) Error() string {
	return "repo-map include confirmation declined; rerun with --include DIR[,DIR...] to choose folders explicitly"
}

func RunMapCLI(ctx context.Context, args []string, stdout, stderr io.Writer, deps MapDependencies) int {
	if isHelpArg(args) {
		printMapUsage(stdout)
		return contract.ExitOK
	}
	deps = mapDependenciesWithDefaults(deps)

opts := MapOptions{Dir: "."}
	var includeFlag string
	fs := flag.NewFlagSet("aidlc map", flag.ContinueOnError)
	fs.SetOutput(stderr)
	fs.StringVar(&opts.Dir, "dir", opts.Dir, "repository directory to map")
	fs.StringVar(&includeFlag, "include", "", "comma-separated folders to include in the repo map")
	fs.BoolVar(&opts.Check, "check", false, "check whether docs/map/index.json is fresh")
	fs.Usage = func() { printMapUsage(stderr) }
	if err := fs.Parse(args); err != nil {
		return contract.ExitUsage
	}
	if fs.NArg() != 0 {
		fs.Usage()
		return contract.ExitUsage
	}

explicitInclude, explicitIncludeSet, err := parseIncludeFlag(includeFlag)
	if err != nil {
		fmt.Fprintf(stderr, "aidlc map: %v\n", err)
		return contract.ExitUsage
	}
	if opts.Check && explicitIncludeSet {
		fmt.Fprintln(stderr, "aidlc map: --include cannot be used with --check; --check uses the saved whitelist")
		return contract.ExitUsage
	}

if opts.Check {
		include, ok, err := templatesync.ReadManifestMapInclude(opts.Dir)
		if err != nil {
			fmt.Fprintf(stderr, "aidlc map: %v\n", err)
			return contract.ExitUsage
		}
		if !ok {
			fmt.Fprintln(stderr, missingIncludeGuidance())
			return contract.ExitUsage
		}
		status, err := repomap.CheckStalenessWithOptions(opts.Dir, repomap.ScanOptions{Include: include})
		if err != nil {
			fmt.Fprintf(stderr, "aidlc map: %v\n", err)
			return contract.ExitUsage
		}
		printStaleness(stdout, status)
		if status.Fresh {
			return contract.ExitOK
		}
		return contract.ExitConflict
	}

result, err := RunMap(context.Background(), MapOptions{Dir: root}, mapTestDependencies())
	if err != nil {
		t.Fatalf("RunMap() error = %v", err)
	}
	if result.Files != 2 {
		t.Fatalf("Files = %d, want 2", result.Files)
	}

assertMapFileExists(t, root, filepath.Join(model.MapDir, model.FilesShard))
	assertMapFileExists(t, root, filepath.Join(model.MapDir, model.IndexFilename))
	assertMapFileExists(t, root, filepath.Join(model.MapDir, model.SQLiteFilename))
	if got := testutil.ReadFile(t, root, filepath.Join(model.MapDir, model.IndexFilename)); !strings.Contains(got, `"content_hash"`) {
		t.Fatalf("index missing file hashes:\n%s", got)
	}
}

func TestMapCLICheckExitCodes(t *testing.T) {
	root := t.TempDir()
	testutil.WriteFile(t, root, "src/main.go", "package main\n")

var stdout, stderr bytes.Buffer
	code := RunMapCLI(context.Background(), []string{"--dir", root, "--include", "src"}, &stdout, &stderr, mapTestDependencies())
	if code != contract.ExitOK {
		t.Fatalf("map code = %d, stderr = %q, stdout = %q", code, stderr.String(), stdout.String())
	}
	if !strings.Contains(stdout.String(), "repo map: built\n") {
		t.Fatalf("stdout missing build summary:\n%s", stdout.String())
	}
	if !strings.Contains(stdout.String(), "include: src\n") {
		t.Fatalf("stdout missing include summary:\n%s", stdout.String())
	}

stdout.Reset()
	stderr.Reset()
	code = RunMapCLI(context.Background(), []string{"--dir", root, "--check"}, &stdout, &stderr, mapTestDependencies())
	if code != contract.ExitOK {
		t.Fatalf("fresh check code = %d, stderr = %q, stdout = %q", code, stderr.String(), stdout.String())
	}
	if got := stdout.String(); got != "repo map: fresh\n" {
		t.Fatalf("fresh stdout = %q", got)
	}

testutil.WriteFile(t, root, "src/main.go", "package main\n\nfunc main() {}\n")
	stdout.Reset()
	stderr.Reset()
	code = RunMapCLI(context.Background(), []string{"--dir", root, "--check"}, &stdout, &stderr, mapTestDependencies())
	if code != contract.ExitConflict {
		t.Fatalf("stale check code = %d, want conflict; stderr = %q, stdout = %q", code, stderr.String(), stdout.String())
	}
	if !strings.Contains(stdout.String(), "repo map: stale\n") || !strings.Contains(stdout.String(), "changed: src/main.go\n") {
		t.Fatalf("stale stdout missing changed file:\n%s", stdout.String())
	}
}

func TestMapCLIContinuesWhenCacheBuildFails(t *testing.T) {
	root := t.TempDir()
	testutil.WriteFile(t, root, "src/main.go", "package main\n")

var stdout, stderr bytes.Buffer
	deps := mapTestDependencies()
	deps.CacheBuilder = failingCacheBuilder{err: errors.New("fts unavailable")}
	code := RunMapCLI(context.Background(), []string{"--dir", root, "--include", "src"}, &stdout, &stderr, deps)
	if code != contract.ExitOK {
		t.Fatalf("map code = %d, stderr = %q, stdout = %q", code, stderr.String(), stdout.String())
	}
	if !strings.Contains(stdout.String(), "cache: unavailable: fts unavailable\n") {
		t.Fatalf("stdout missing cache failure status:\n%s", stdout.String())
	}
	assertMapFileExists(t, root, filepath.Join(model.MapDir, model.FilesShard))
	assertMapFileExists(t, root, filepath.Join(model.MapDir, model.IndexFilename))
}

type QueryDependencies struct {
	NewCacheQuerier func(mapDir string) model.Querier
}

func RunQueryCLI(ctx context.Context, args []string, stdout, stderr io.Writer, deps QueryDependencies) int {
	if isHelpArg(args) {
		printQueryUsage(stdout)
		return contract.ExitOK
	}

text, err := RunQuery(ctx, QueryOptions{
		TargetDir: dir,
		Query:     query,
		Limit:     limit,
		Shard:     shard,
	}, deps)
	if err != nil {
		fmt.Fprintf(stderr, "aidlc query: %v\n", err)
		return contract.ExitUsage
	}
	fmt.Fprint(stdout, text)
	return contract.ExitOK
}

type QueryOptions struct {
	TargetDir string
	Query     string
	Limit     int
	Shard     string
}

func RunQuery(ctx context.Context, opts QueryOptions, deps QueryDependencies) (string, error) {
	if opts.TargetDir == "" {
		opts.TargetDir = "."
	}
	if opts.Limit < 0 {
		return "", fmt.Errorf("--limit must be non-negative")
	}
	mapDir := filepath.Join(opts.TargetDir, filepath.FromSlash(model.MapDir))
	querier := queryQuerier(mapDir, opts.Shard, deps)
	return repomap.NewQueryEngine(querier).QueryText(ctx, opts.Query, opts.Limit, opts.Shard)
}

func queryQuerier(mapDir, shard string, deps QueryDependencies) model.Querier {
	fallback := repomap.NewFallbackQuerier(mapDir)
	if strings.TrimSpace(shard) != "" {
		return fallback
	}
	if _, err := os.Stat(filepath.Join(mapDir, model.SQLiteFilename)); err == nil && deps.NewCacheQuerier != nil {
		return cacheFallbackQuerier{
			primary:  deps.NewCacheQuerier(mapDir),
			fallback: fallback,
		}
	}
	return fallback
}

type cacheFallbackQuerier struct {
	primary  model.Querier
	fallback model.Querier
}

func (q cacheFallbackQuerier) Query(ctx context.Context, query string, limit int) ([]model.QueryResult, error) {
	results, err := q.primary.Query(ctx, query, limit)
