func RunVersionCLI(args []string, stdout, stderr io.Writer) int {
	if len(args) > 0 {
		if isHelpArg(args) {
			fmt.Fprintln(stdout, "Usage: aidlc version")
			return contract.ExitOK
		}
		fmt.Fprintf(stderr, "aidlc version: unexpected argument %q\n", args[0])
		return contract.ExitUsage
	}
	fmt.Fprintf(stdout, "aidlc %s\n", CurrentVersion())
	return contract.ExitOK
}

func CurrentVersion() string {
	if Version != "" && Version != "dev" {
		return Version
	}
	if info, ok := debug.ReadBuildInfo(); ok {
		version := strings.TrimSpace(info.Main.Version)
		if version != "" && version != "(devel)" {
			return version
		}
	}
	if Version == "" {
		return "dev"
	}
	return Version
}

func SupportedIDEs() []IDE {
	out := make([]IDE, len(supportedIDEs))
	copy(out, supportedIDEs)
	return out
}

func ConcreteIDEs() []IDE {
	out := make([]IDE, len(concreteIDEs))
	copy(out, concreteIDEs)
	return out
}

func ParseIDE(value string) (IDE, error) {
	ide := IDE(value)
	for _, supported := range supportedIDEs {
		if ide == supported {
			return ide, nil
		}
	}
	return "", fmt.Errorf("unsupported IDE %q", value)
}

func (i IDE) String() string {
	return string(i)
}

func (i IDE) IsAggregate() bool {
	return i == IDEAll
}

func NormalizeIDESelection(values []IDE) ([]IDE, error) {
	selected := make(map[IDE]bool, len(concreteIDEs))
	for _, value := range values {
		if value == "" {
			continue
		}
		ide, err := ParseIDE(value.String())
		if err != nil {
			return nil, err
		}
		if ide.IsAggregate() {
			for _, concrete := range concreteIDEs {
				selected[concrete] = true
			}
			continue
		}
		selected[ide] = true
	}

