func loadDocuments(dir string) ([]document, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", dir, err)
	}
	var names []string
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".md") {
			names = append(names, entry.Name())
		}
	}
	sort.Strings(names)
	if len(names) == 0 {
		return nil, fmt.Errorf("%s: no markdown documents found", dir)
	}
	docs := make([]document, 0, len(names))
	for _, name := range names {
		doc, err := loadDocument(filepath.Join(dir, name))
		if err != nil {
			return nil, err
		}
		docs = append(docs, doc)
	}
	return docs, nil

func loadDocument(path string) (document, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return document{}, err
	}
	frontmatter, body, err := splitFrontmatter(string(content))
	if err != nil {
		return document{}, fmt.Errorf("%s: %w", path, err)
	}
	values := parseSimpleYAML(frontmatter)
	name := values["name"]
	if name == "" {
		name = strings.TrimSuffix(filepath.Base(path), filepath.Ext(path))
	}
	description := values["description"]
	if description == "" {
		return document{}, fmt.Errorf("%s: frontmatter missing required 'description'", path)
	}
	return document{Name: name, Description: description, Body: stripBlankEdges(body), Raw: content}, nil
}

func splitFrontmatter(content string) (string, string, error) {
	content = strings.ReplaceAll(content, "\r\n", "\n")
	if !strings.HasPrefix(content, "---\n") {
		return "", "", fmt.Errorf("missing YAML frontmatter")
	}
	rest := strings.TrimPrefix(content, "---\n")
	idx := strings.Index(rest, "\n---")
	if idx < 0 {
		return "", "", fmt.Errorf("unterminated frontmatter")
	}
	frontmatter := rest[:idx]
	body := rest[idx+len("\n---"):]
	body = strings.TrimPrefix(body, "\n")
	return frontmatter, body, nil
}

func parseSimpleYAML(content string) map[string]string {
	out := map[string]string{}
	for _, raw := range strings.Split(content, "\n") {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, value, ok := strings.Cut(line, ":")
		if !ok {
			continue
		}
		out[strings.TrimSpace(key)] = stripYAMLString(strings.TrimSpace(value))
	}
	return out
}

func stripYAMLString(value string) string {
	if len(value) >= 2 {
		first, last := value[0], value[len(value)-1]
		if (first == '\'' || first == '"') && first == last {
			return value[1 : len(value)-1]
		}
	}
	return value
}

func loadSharedBody(path string) (string, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	lines := strings.Split(strings.ReplaceAll(string(content), "\r\n", "\n"), "\n")
	found := false
	started := false
	inComment := false
	var out []string
	for _, line := range lines {
		if !found {
			if strings.Contains(line, readmeInitMarker) {
				found = true
			}
			continue
		}
		if !started && line == "" {
			continue
		}
		if !started && strings.HasPrefix(line, "<!--") {
			inComment = !strings.Contains(line, "-->")
			continue
		}

if inComment {
			if strings.Contains(line, "-->") {
				inComment = false
			}
			continue
		}
		if !started && line == "" {
			continue
		}
		started = true
		out = append(out, line)
	}
	if !found {
		return "", fmt.Errorf("%s: missing %s", path, readmeInitMarker)
	}
	return strings.Join(out, "\n"), nil
}

func ParseChecksums(r io.Reader) (ChecksumSet, error) {
	checksums := ChecksumSet{}
	scanner := bufio.NewScanner(r)
	lineNumber := 0
	for scanner.Scan() {
		lineNumber++
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		sum, name, ok := parseChecksumLine(line)
		if !ok {
			return nil, fmt.Errorf("parse checksums line %d: expected '<sha256> <filename>'", lineNumber)
		}
		checksums[name] = strings.ToLower(sum)
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("read checksums: %w", err)
	}
	return checksums, nil
}

func VerifyChecksum(r io.Reader, filename string, checksums ChecksumSet) error {
	want, ok := checksums[filename]
	if !ok {
		return fmt.Errorf("checksum for %s not found", filename)
	}
	if len(want) != sha256.Size*2 {
		return fmt.Errorf("checksum for %s is not a SHA-256 digest", filename)
	}
	hash := sha256.New()
	if _, err := io.Copy(hash, r); err != nil {
		return fmt.Errorf("hash %s: %w", filename, err)
	}
	got := hex.EncodeToString(hash.Sum(nil))
	if got != strings.ToLower(want) {
		return fmt.Errorf("checksum mismatch for %s", filename)
	}
	return nil
}

func parseChecksumLine(line string) (string, string, bool) {
	fields := strings.Fields(line)
	if len(fields) < 2 {
		return "", "", false
	}
	sum := fields[0]
	if len(sum) != sha256.Size*2 {
		return "", "", false
	}
	if _, err := hex.DecodeString(sum); err != nil {
		return "", "", false
	}
	name := strings.TrimPrefix(fields[1], "*")
	if name == "" || strings.Contains(name, "/") || strings.Contains(name, `\`) {
		return "", "", false
	}
	return sum, name, true
}

