func (a Archive) Snapshot(ctx context.Context) (Snapshot, error) {
	reader, err := zip.NewReader(bytes.NewReader(a.Data), int64(len(a.Data)))
	if err != nil {
		return Snapshot{}, fmt.Errorf("open archive: %w", err)
	}

root := strings.Trim(strings.ReplaceAll(a.Root, "\\", "/"), "/")
	entries := make(map[string]*zip.File, len(reader.File))
	for _, file := range reader.File {
		if err := ctx.Err(); err != nil {
			return Snapshot{}, err
		}
		if file.FileInfo().IsDir() {
			continue
		}
		name := strings.TrimPrefix(file.Name, "/")
		if root != "" {
			name = strings.TrimPrefix(name, root+"/")
		} else if first, rest, ok := strings.Cut(name, "/"); ok && strings.Contains(first, "-") {
			name = rest
		}
		entries[path.Clean(name)] = file
	}

manifestFile, ok := entries[contract.TemplateManifestPath]
	if !ok {
		return Snapshot{}, fmt.Errorf("archive missing %s", contract.TemplateManifestPath)
	}
	manifestBytes, err := readZipFile(manifestFile)
	if err != nil {
		return Snapshot{}, fmt.Errorf("read template manifest: %w", err)
	}
	manifest, err := ParseTemplateManifest(manifestBytes)
	if err != nil {
		return Snapshot{}, err
	}
	includeEntries, err := ManifestIncludeEntries(manifest)
	if err != nil {
		return Snapshot{}, err
	}

files := make([]File, 0, len(includeEntries))
	for _, entry := range includeEntries {
		file, ok := entries[entry.SourcePath]
		if !ok {
			return Snapshot{}, fmt.Errorf("archive missing payload file %s", entry.SourcePath)
		}
		content, err := readZipFile(file)
		if err != nil {
			return Snapshot{}, fmt.Errorf("read payload file %s: %w", entry.SourcePath, err)
		}
		files = append(files, File{Path: entry.TargetPath, Content: content, Mode: file.Mode().Perm()})
	}

snapshot := Snapshot{
		Manifest: manifest,
		Upstream: contract.UpstreamRef{
			Source: a.Source,
			Ref:    a.Ref,
			Commit: a.Commit,
		},
		Files: files,
	}
	if snapshot.Upstream.Source == "" {
		snapshot.Upstream.Source = "archive"
	}
	return snapshot, ValidateSnapshot(snapshot)
}

func readZipFile(file *zip.File) ([]byte, error) {
	rc, err := file.Open()
	if err != nil {
		return nil, err
	}
	defer rc.Close()
	return io.ReadAll(rc)
}

type GitHub struct {
	Owner      string
	Repo       string
	Ref        string
	HTTPClient *http.Client
}

func (g GitHub) Snapshot(ctx context.Context) (Snapshot, error) {
	if g.Owner == "" || g.Repo == "" {
		return Snapshot{}, fmt.Errorf("github owner and repo are required")
	}
	ref := g.Ref
	if ref == "" {
		ref = "main"
	}
	url := fmt.Sprintf("https://github.com/%s/%s/archive/%s.zip", g.Owner, g.Repo, ref)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return Snapshot{}, err
	}
	client := g.HTTPClient
	if client == nil {
		client = http.DefaultClient
	}
	resp, err := client.Do(req)
	if err != nil {
		return Snapshot{}, fmt.Errorf("fetch github archive: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return Snapshot{}, fmt.Errorf("fetch github archive: %s", resp.Status)

}
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return Snapshot{}, fmt.Errorf("read github archive: %w", err)
	}
	return Archive{
		Data:   data,
		Source: strings.TrimSuffix(url, ".zip"),
		Ref:    ref,
		Commit: resp.Header.Get("ETag"),
	}.Snapshot(ctx)
}

