		if err := ctx.Err(); err != nil {
			return Snapshot{}, err
		}
		fullPath := filepath.Join(root, filepath.FromSlash(entry.SourcePath))
		info, err := os.Stat(fullPath)
		if err != nil {
			return Snapshot{}, fmt.Errorf("stat payload file %s: %w", entry.SourcePath, err)
