		if err != nil {
			return Snapshot{}, fmt.Errorf("read payload file %s: %w", entry.SourcePath, err)
		}
		files = append(files, File{Path: entry.TargetPath, Content: content, Mode: info.Mode().Perm()})
	}

snapshot := Snapshot{
		Manifest: manifest,
		Upstream: contract.UpstreamRef{
			Source: l.Source,
			Ref:    l.Ref,
			Commit: l.Commit,
		},
		Files: files,
	}
	if snapshot.Upstream.Source == "" {
		snapshot.Upstream.Source = "local"
	}
	return snapshot, ValidateSnapshot(snapshot)
}

