func TestValidateSnapshotRejectsInvalidMappedPayload(t *testing.T) {
	tests := []struct {
		name     string
		include  []string
		mappings []contract.TemplatePayloadMapping
		files    []File
		want     string
	}{
		{
			name:     "absolute source",
