func Authorize(name string) string {
	return core.Greet(NormalizePrincipal(name))
}

func NormalizePrincipal(name string) string {
	return core.NormalizeGreetingName(name)
}

func TestAuthorize(t *testing.T) {
	if got := Authorize("agent"); got != "hello agent" {
		t.Fatalf("Authorize() = %q", got)
	}
}

func Greet(name string) string {
	return "hello " + NormalizeGreetingName(name)
}

func NormalizeGreetingName(name string) string {
	return strings.TrimSpace(name)
}

func TestGreet(t *testing.T) {
	if got := Greet(" agent "); got != "hello agent" {
		t.Fatalf("Greet() = %q", got)
	}
}

